<template><dialog ref="dialog" class="ui-dialog" :aria-label="title" @cancel="close" @close="onClosed" @click="backdrop"><div class="dialog-header"><div><div v-if="eyebrow" class="eyebrow">{{ eyebrow }}</div><h2>{{ title }}</h2></div><button class="btn btn-ghost btn-square" aria-label="关闭对话框" @click="close"><UiIcon name="close"/></button></div><div class="dialog-body"><slot/></div><div v-if="$slots.footer" class="dialog-footer"><slot name="footer"/></div></dialog></template>
<script>
import UiIcon from './UiIcon.vue'
export default {name:'UiDialog',components:{UiIcon},emits:['update:modelValue'],props:{modelValue:Boolean,title:String,eyebrow:String},watch:{modelValue(value){this.$nextTick(()=>{if(value&&!this.$refs.dialog.open)this.$refs.dialog.showModal();if(!value&&this.$refs.dialog.open)this.$refs.dialog.close()})}},mounted(){if(this.modelValue)this.$refs.dialog.showModal()},beforeUnmount(){this.$refs.dialog?.close()},methods:{close(){this.$emit('update:modelValue',false)},onClosed(){this.$emit('update:modelValue',false)},backdrop(event){if(event.target!==this.$refs.dialog)return;const r=this.$refs.dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)this.close()}}}
</script>
